exploreUrl:
@js: var result = [];
java.toast("🔥动态获取发现中……");
var push=(title,url,size)=>result.push({
  	"title": title,
  	"url": url,
  	"style": {
   "layout_flexGrow": 1,
   "layout_flexBasisPercent": size
   }
 });
var top = java.ajax("http://www.shukuge.com");
if (top) {
a=org.jsoup.Jsoup.parse(top).select(".swiper-wrapper.clearfix a");
push("分类",null,1)
    for(var i=1;i<a.length;i++){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.3;
        url=url+"1"
        url=String(url).replace(/1$/,"{{page}}")
        push(title,url,size)
    };
      } else { 
      java.toast("🚫发现获取失败……");
}
JSON.stringify(result);

